INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES (10118, "フリーマーケット会場", 20063115, 1, "フリーマーケットを訪れたジータが出会ったのは\n城をこっそり抜け出していたペコリーヌだった。", 91002, 7, "青空の下で謁見", 2, 0, 2834, "ペコリーヌとの出会い", 5118061, 40, 8);
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES (10118, "フリーマーケット会場", 20063115, 1, "ジータたちがフリーマーケットを巡っていると\n露店を出していたマホに声をかけられる。", 91002, 7, "未来の騎空団\nマスコット？", 2, 0, 2835, "マホとの出会い", 5118062, 40, 8);
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES (10118, "ランドソル市街地", 20063115, 1, "ジータが騎空団への依頼を確認していると、\n高笑いをしながらアキノが現れる。", 91002, 7, "お嬢さまからの\n緊急依頼", 2, 0, 2837, "アキノとの出会い", 5118063, 40, 8);
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES (10118, "フリーマーケット会場", 20063115, 1, "ジータたちは、フリーマーケット会場で\n少し困った様子のジュンを見かける。", 91002, 18, "黄金色の悩みごと", 2, 0, 4108402, "ジュンとの出会い", 5118064, 40, 8);
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES (10118, "フリーマーケット会場", 20063115, 1, "フリーマーケットの隅で開かれる格闘大会──\nそこにはカオリもいて……？", 91002, 18, "白熱！　格闘大会！", 2, 0, 4107402, "カオリとの出会い", 5118065, 40, 8);
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES (10118, "オーエド町", 20063115, 1, "太鼓祭を控えるオーエド町──\nジータは、困った様子のニノンと出会う。", 91002, 16, "祭り太鼓はオーエドの華", 2, 1, 9000227, "ニノンとの出会い", 5118066, 40, 8);
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES (10118, "フリーマーケット会場", 20063115, 1, "ビカラはイベントに出演中のスズナを見かける。\nしかし、スズナはどこか困っているようで……？", 91002, 19, "人気者は遅れて\nやってくる", 3, 0, 2101181, "スズナとの出会い", 5118067, 40, 8);
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES (10118, "ランドソル市街地", 20063115, 1, "ビカラたちが街を散策していると、通りかかった\nナナカが興奮した様子で近づいてきて……？", 91002, 18, "巫女・ミーツ・魔法少女", 3, 0, 4109402, "ナナカとの出会い", 5118068, 40, 8);
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES (10118, "フリーマーケット会場", 20063115, 1, "ネズ耳をなくしてしまい絶望するビカラ。同じ頃\nキャルとコッコロは落とし物を拾っており……", 91002, 18, "ネズ耳は二度なくなる", 3, 0, 4305402, "キャル＆コッコロとの出会い", 5118069, 40, 8);
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES (10118, "ランドソル市街地", 20063115, 1, "街外れでひと休みをしていたビカラたちは、\nすっかりゴキゲンな様子のユカリと出会う。", 91002, 18, "この出会いにカンパイ！", 3, 0, 4101402, "ユカリとの出会い", 5118070, 40, 8);
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES (10118, "ランドソル市街地", 20063115, 1, "ビカラは、人混みに怯えるアオイを心配し、\n陽気に声をかけるも……", 91002, 18, "陰陽アンサンブル", 3, 0, 4106402, "アオイとの出会い", 5118071, 40, 8);
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES (10118, "フリーマーケット会場", 20063115, 1, "ビカラがフリーマーケット会場を歩いていると\n占いをしていたシノブに声をかけられる。", 91002, 7, "運試し十番勝負！", 3, 1, 2836, "シノブとの出会い", 5118072, 40, 8);
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES (10118, 0, 20063115, 0, 0, 0, 0, "彼女たちの新たな日常", 1, 0, 0, "オープニング", 5118600, 0, 0);
